/* ---------- Calculators ---------- */
window.CALCS = [
 {id:"ckd", n:"СКФ по CKD-EPI (2021)", f:[{k:"scr",l:"Креатинин, мкмоль/л",t:"n"},{k:"age",l:"Возраст, годы",t:"n"},{k:"sex",l:"Пол",t:"s",o:["Мужской","Женский"]}],
  c:v=>{const scr=+v.scr/88.4, k=v.sex==="Женский"?0.7:0.9, a=v.sex==="Женский"?-0.241:-0.302;
   const g=142*Math.min(scr/k,1)**a*Math.max(scr/k,1)**-1.2*0.9938**(+v.age)*(v.sex==="Женский"?1.012:1);
   let i=g>=90?"ХБП C1 (норма или высокая)":g>=60?"ХБП C2 (слегка снижена)":g>=45?"ХБП C3a":g>=30?"ХБП C3b":g>=15?"ХБП C4 (тяжёлое снижение)":"ХБП C5 (почечная недостаточность)";
   return {v:g.toFixed(1)+" мл/мин/1.73м²", i};}},
 {id:"cg", n:"Клиренс креатинина (Cockcroft-Gault)", f:[{k:"scr",l:"Креатинин, мкмоль/л",t:"n"},{k:"age",l:"Возраст, годы",t:"n"},{k:"w",l:"Вес, кг",t:"n"},{k:"sex",l:"Пол",t:"s",o:["Мужской","Женский"]}],
  c:v=>{const cl=(140-+v.age)*+v.w/(72*(+v.scr/88.4))*(v.sex==="Женский"?0.85:1);
   let i=cl>=90?"Нормальная функция":cl>=60?"Лёгкое снижение":cl>=30?"Умеренное снижение — коррекция доз препаратовом":"Тяжёлое снижение — избегать нефротоксичных";
   return {v:cl.toFixed(1)+" мл/мин", i};}},
 {id:"bmi", n:"ИМТ (индекс массы тела)", f:[{k:"w",l:"Вес, кг",t:"n"},{k:"h",l:"Рост, см",t:"n"}],
  c:v=>{const b=+v.w/(+v.h/100)**2;
   let i=b<18.5?"Недостаточный вес":b<25?"Норма":b<30?"Избыточный вес":b<35?"Ожирение I ст.":b<40?"Ожирение II ст.":"Ожирение III ст. (морбидное)";
   return {v:b.toFixed(1)+" кг/м²", i};}},
 {id:"gcs", n:"Шкала комы Глазго (GCS)", f:[{k:"e",l:"Открывание глаз (1–4)",t:"n"},{k:"v",l:"Речь (1–5)",t:"n"},{k:"m",l:"Движения (1–6)",t:"n"}],
  c:v=>{const g=(+v.e)+(+v.v)+(+v.m);
   let i=g>=13?"Лёгкая ЧМТ / сознание сохранено":g>=9?"Умеренная ЧМТ":"Тяжёлая ЧМТ / кома (≤8 — интубация!)";
   return {v:g+" баллов", i};}},
 {id:"pgcs", n:"Педиатрическая шкала Глазго (вербальные ответы)", f:[{k:"e",l:"Глаза (1–4)",t:"n"},{k:"v",l:"Речь: улыбка/ориентация 6 … плач 1 (дети)",t:"n"},{k:"m",l:"Движения (1–6)",t:"n"}],
  c:v=>{const g=(+v.e)+(+v.v)+(+v.m); return {v:g+" баллов", i:g>=13?"Лёгкая ЧМТ":g>=9?"Умеренная":"Тяжёлая (интубация при ≤8)"};}},
 {id:"wells", n:"Шкала Wells (вероятность ТЭЛА)", f:[{k:"dvt",l:"Клиника ТГВ (3)",t:"s",o:["Нет","Да"]},{k:"pe1",l:"ТЭЛА — наиболее вероятный диагноз (3)",t:"s",o:["Нет","Да"]},{k:"hr",l:"ЧСС >100 (1.5)",t:"s",o:["Нет","Да"]},{k:"imm",l:"Иммобилизация/операция 4 нед (1.5)",t:"s",o:["Нет","Да"]},{k:"hist",l:"ТЭЛА/ТГВ в анамнезе (1.5)",t:"s",o:["Нет","Да"]},{k:"hem",l:"Кровохарканье (1)",t:"s",o:["Нет","Да"]},{k:"cancer",l:"Злокачественное новообразование (1)",t:"s",o:["Нет","Да"]}],
  c:v=>{const s=+(v.dvt==="Да")*3+(v.pe1==="Да")*3+(v.hr==="Да")*1.5+(v.imm==="Да")*1.5+(v.hist==="Да")*1.5+(v.hem==="Да")*1+(v.cancer==="Да")*1;
   let i=s<2?"Низкая вероятность (≈1.3% ТЭЛА) — возможен Д-димер":s<=6?"Умеренная (≈16.5%) — визуализация":"Высокая (≈37.5%) — немедленная КТА/эхо";
   return {v:s+" баллов", i};}},
 {id:"chads", n:"CHA₂DS₂-VASc (риск инсульта при ФП)", f:[{k:"chf",l:"ХСН (1)",t:"s",o:["Нет","Да"]},{k:"htn",l:"Гипертензия (1)",t:"s",o:["Нет","Да"]},{k:"a75",l:"Возраст ≥75 (2)",t:"s",o:["Нет","Да"]},{k:"dm",l:"Диабет (1)",t:"s",o:["Нет","Да"]},{k:"stroke",l:"Инсульт/ТИА/тромбоэмболия (2)",t:"s",o:["Нет","Да"]},{k:"vasc",l:"Сосудистая болезнь (1)",t:"s",o:["Нет","Да"]},{k:"a65",l:"Возраст 65–74 (1)",t:"s",o:["Нет","Да"]},{k:"sex",l:"Женский пол (1)",t:"s",o:["Нет","Да"]}],
  c:v=>{const s=+(v.chf==="Да")+(v.htn==="Да")+(v.a75==="Да")*2+(v.dm==="Да")+(v.stroke==="Да")*2+(v.vasc==="Да")+(v.a65==="Да")+(v.sex==="Да");
   let i=s===0?"Низкий — антикоагулянты не показаны":s===1?"Умеренный — рассмотреть ОАК":"Высокий — показана антикоагуляция (DOAC)";
   return {v:s+" баллов", i};}},
 {id:"curb", n:"CURB-65 (тяжесть пневмонии)", f:[{k:"c",l:"Спутанность сознания",t:"s",o:["Нет","Да"]},{k:"u",l:"Мочевина >7 ммоль/л",t:"s",o:["Нет","Да"]},{k:"r",l:"ЧДД ≥30",t:"s",o:["Нет","Да"]},{k:"bp",l:"САД <90 или ДАД ≤60",t:"s",o:["Нет","Да"]},{k:"a",l:"Возраст ≥65",t:"s",o:["Нет","Да"]}],
  c:v=>{const s=+(v.c==="Да")+(v.u==="Да")+(v.r==="Да")+(v.bp==="Да")+(v.a==="Да");
   let i=s<=1?"Амбулаторное лечение":s===2?"Краткосрочная госпитализация":"≥3 — тяжёлая пневмония, рассмотреть ОРИТ";
   return {v:s+" баллов", i};}},
 {id:"map", n:"Среднее артериальное давление (MAP)", f:[{k:"s",l:"САД, мм рт.ст.",t:"n"},{k:"d",l:"ДАД, мм рт.ст.",t:"n"}],
  c:v=>{const m=(+v.s+2*+v.d)/3; return {v:m.toFixed(0)+" мм рт.ст.", i:m>=65?"Адекватная перфузия":"<65 — гипоперфузия (шок)"};}},
 {id:"ag", n:"Анионная щель", f:[{k:"na",l:"Натрий, ммоль/л",t:"n"},{k:"cl",l:"Хлор, ммоль/л",t:"n"},{k:"hco3",l:"Бикарбонат, ммоль/л",t:"n"}],
  c:v=>{const a=(+v.na)-(+v.cl)-(+v.hco3);
   let i=a>=8&&a<=12?"Норма (8–12)":a>12?"Повышена — метаболический ацидоз с повышенной анионной щелью (лактат, кето, уремия, токсины)":"Нормальная или низкая — потери HCO3 (диарея, ПТА)";
   return {v:a+" ммоль/л", i};}},
 {id:"nacorr", n:"Коррекция натрия по гликемии", f:[{k:"na",l:"Натрий измеренный, ммоль/л",t:"n"},{k:"glu",l:"Глюкоза, ммоль/л",t:"n"}],
  c:v=>{const c=+v.na+0.3*(+v.glu-5.5);
   return {v:c.toFixed(1)+" ммоль/л", i:"Скорректированный Na (глюкоза «вытесняет» натрий). Ориентируйтесь на него при оценке тоничности"};}},
 {id:"osm", n:"Осмолярность плазмы", f:[{k:"na",l:"Натрий, ммоль/л",t:"n"},{k:"glu",l:"Глюкоза, ммоль/л",t:"n"},{k:"un",l:"Мочевина, ммоль/л",t:"n"}],
  c:v=>{const o=2*+v.na+ +v.glu+ +v.un;
   let i=o>=275&&o<=295?"Норма":o>295?"Гиперосмолярность":"Гипоосмолярность";
   return {v:o+" мосм/кг", i};}},
 {id:"ldl", n:"ЛПНП по Фридвальду", f:[{k:"tc",l:"Общий холестерин, ммоль/л",t:"n"},{k:"hdl",l:"ЛПВП, ммоль/л",t:"n"},{k:"tg",l:"Триглицериды, ммоль/л",t:"n"}],
  c:v=>{if(+v.tg>=4.5) return {v:"—", i:"ТГ ≥4.5 — формула неприменима, нужен прямой ЛПНП"};
   const l=(+v.tc)-(+v.hdl)-(+v.tg/2.2); return {v:l.toFixed(2)+" ммоль/л", i:l<1.8?"Цель при очень высоком риске достигнута":l<3.0?"Цель при высоком/умеренном риске":"Выше цели — рассмотреть терапию"};}},
 {id:"apgar", n:"Шкала Апгар (новорождённые)", f:[{k:"skin",l:"Окраска кожи (0–2)",t:"n"},{k:"hr",l:"Пульс (0–2)",t:"n"},{k:"grim",l:"Рефлекторная возбудимость (0–2)",t:"n"},{k:"tone",l:"Мышечный тонус (0–2)",t:"n"},{k:"resp",l:"Дыхание (0–2)",t:"n"}],
  c:v=>{const s=[+v.skin,+v.hr,+v.grim,+v.tone,+v.resp].reduce((a,b)=>a+b,0);
   let i=s>=7?"Норма":s>=4?"Умеренная асфиксия":"Тяжёлая асфиксия — реанимация!";
   return {v:s+" баллов (1 и 5 мин)", i};}},
 {id:"dose", n:"Расчёт дозировки мг/кг", f:[{k:"w",l:"Вес, кг",t:"n"},{k:"mg",l:"Доза, мг/кг",t:"n"},{k:"conc",l:"Концентрация раствора, мг/мл (необязат.)",t:"n"}],
  c:v=>{const d=+v.w*+v.mg; const ml=v.conc?d/+v.conc:null;
   return {v:d.toFixed(1)+" мг"+(ml?" = "+ml.toFixed(2)+" мл":""), i:"Пересчитайте на количество ампул/флаконов и проверьте максимально допустимую дозу"};}},
 {id:"qtc", n:"Корректированный QT (Bazett)", f:[{k:"qt",l:"QT, мс",t:"n"},{k:"rr",l:"RR, мс",t:"n"}],
  c:v=>{const q=+v.qt/Math.sqrt(+v.rr/1000);
   let i=q<440?"Норма":q<=460?"Пограничное":"Удлинение QT — риск Torsades de pointes";
   return {v:Math.round(q)+" мс", i};}},
 {id:"caca", n:"Коррекция кальция по альбумину", f:[{k:"ca",l:"Кальций общий, ммоль/л",t:"n"},{k:"alb",l:"Альбумин, г/л",t:"n"}],
  c:v=>{const c=+v.ca+0.02*(40-+v.alb);
   let i=c>=2.15&&c<=2.55?"Норма":c<2.15?"Гипокальциемия (скорректированная)":"Гиперкальциемия";
   return {v:c.toFixed(2)+" ммоль/л", i};}}
];
